<?php
declare(strict_types=1);
require_once __DIR__.'/../config/conexion.php';
require_once __DIR__.'/auth.php';
if(!function_exists('validar_post_csrf')){function validar_post_csrf(): void {if($_SERVER['REQUEST_METHOD']==='POST'&&!validar_csrf($_POST['csrf']??null)){http_response_code(419);exit('Token CSRF invalido.');}}}
function directorio_respaldos(): string {$dir=dirname(__DIR__).DIRECTORY_SEPARATOR.'backups';if(!is_dir($dir))mkdir($dir,0750,true);return $dir;}
function nombre_respaldo_valido(string $nombre): bool{return(bool)preg_match('/^supay_[0-9]{8}_[0-9]{6}\.sql$/',$nombre);}
function ruta_respaldo_segura(string $nombre): string{if(!nombre_respaldo_valido($nombre))throw new InvalidArgumentException('Nombre de respaldo invalido.');$ruta=realpath(directorio_respaldos());if($ruta===false)throw new RuntimeException('No existe la carpeta de respaldos.');return $ruta.DIRECTORY_SEPARATOR.$nombre;}
function valor_sql(PDO $db,mixed $valor): string{return $valor===null?'NULL':$db->quote((string)$valor);}
function respaldo_php(PDO $db,string $ruta): void{$tablas=['usuario','cliente','instrumento','reparacion','proveedor','material','repuesto_utilizado','movimiento_inventario','venta','cobro','bitacora'];$sql="-- SUPAY_BACKUP_VERSION:1\n-- SUPAY_BACKUP_MODE:PHP\nSET FOREIGN_KEY_CHECKS=0;\n";foreach($tablas as $tabla){$sql.='DELETE FROM `'.$tabla."`;\n";$filas=$db->query('SELECT * FROM `'.$tabla.'`')->fetchAll();foreach($filas as $fila){$columnas=array_map(static fn($c)=>'`'.$c.'`',array_keys($fila));$valores=array_map(fn($v)=>valor_sql($db,$v),array_values($fila));$sql.='INSERT INTO `'.$tabla.'` ('.implode(',',$columnas).') VALUES ('.implode(',',$valores).');'."\n";}}$sql.="SET FOREIGN_KEY_CHECKS=1;\n";$tmp=$ruta.'.tmp';if(file_put_contents($tmp,$sql,LOCK_EX)===false||!rename($tmp,$ruta))throw new RuntimeException('No se pudo guardar el respaldo.');}
function argumento_cmd(string $valor): string{return '"'.str_replace('"','\\"',$valor).'"';}
function comando_mysqldump(): ?string{$candidatos=[defined('MYSQLDUMP_PATH')?MYSQLDUMP_PATH:'','D:\\xamppP\\mysql\\bin\\mysqldump.exe','mysqldump'];foreach($candidatos as $c){if($c!==''&&(($c!=='mysqldump'&&is_file($c))||($c==='mysqldump'&&shell_exec('where mysqldump 2>NUL'))))return $c;}return null;}
function crear_respaldo(PDO $db): string{$nombre='supay_'.date('Ymd_His').'.sql';$ruta=ruta_respaldo_segura($nombre);$dump=comando_mysqldump();if($dump){$comando=argumento_cmd($dump).' --host='.argumento_cmd(DB_HOST).' --port='.argumento_cmd(DB_PORT).' --user='.argumento_cmd(DB_USER).' --password='.argumento_cmd(DB_PASS).' --no-create-info --skip-triggers --skip-lock-tables --skip-add-locks --compact --result-file='.argumento_cmd($ruta).' '.argumento_cmd(DB_NAME);exec($comando.' 2>NUL',$salida,$estado);if($estado===0&&is_file($ruta)&&filesize($ruta)>0){$contenido=file_get_contents($ruta);file_put_contents($ruta,"-- SUPAY_BACKUP_VERSION:1\n-- SUPAY_BACKUP_MODE:MYSQLDUMP\n".$contenido,LOCK_EX);return $nombre;}if(is_file($ruta))unlink($ruta);}respaldo_php($db,$ruta);return $nombre;}
function respaldos_existentes(): array{$archivos=glob(directorio_respaldos().DIRECTORY_SEPARATOR.'supay_*.sql')?:[];$lista=[];foreach($archivos as $archivo){$nombre=basename($archivo);if(nombre_respaldo_valido($nombre))$lista[]=['nombre'=>$nombre,'fecha'=>date('Y-m-d H:i:s',filemtime($archivo)),'tamano'=>filesize($archivo)];}usort($lista,static fn($a,$b)=>strcmp($b['nombre'],$a['nombre']));return $lista;}
function limpiar_datos_para_restaurar(PDO $db): void{$tablas=['bitacora','cobro','venta','movimiento_inventario','repuesto_utilizado','reparacion','material','proveedor','instrumento','cliente','usuario'];$db->exec('SET FOREIGN_KEY_CHECKS=0');foreach($tablas as $tabla)$db->exec('DELETE FROM `'.$tabla.'`');}
function restaurar_respaldo(PDO $db,string $nombre): void{$ruta=ruta_respaldo_segura($nombre);if(!is_file($ruta)||filesize($ruta)>50*1024*1024)throw new InvalidArgumentException('El archivo no existe o supera el limite permitido.');$contenido=file_get_contents($ruta);if($contenido===false||strpos($contenido,"-- SUPAY_BACKUP_VERSION:1")!==0)throw new InvalidArgumentException('El archivo no es un respaldo SUPAY valido.');$db->beginTransaction();try{limpiar_datos_para_restaurar($db);$db->exec($contenido);$db->exec('SET FOREIGN_KEY_CHECKS=1');$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$db->exec('SET FOREIGN_KEY_CHECKS=1');throw new RuntimeException('No se pudo restaurar el respaldo.');}}
